if (polygon.size() < 3) {
    return false;
}
std::size_t n = polygon.size();
CGAL::Orientation first_non_collinear = CGAL::COLLINEAR;
// Find the first non‑collinear orientation to establish the turning direction
for (std::size_t i = 0; i < n; ++i) {
    const auto& a = polygon[i];
    const auto& b = polygon[(i + 1) % n];
    const auto& c = polygon[(i + 2) % n];
    CGAL::Orientation o = CGAL::orientation(a, b, c);
    if (o != CGAL::COLLINEAR) {
        first_non_collinear = o;
        break;
    }
}
// If all points are collinear, the polygon is degenerate and not convex
if (first_non_collinear == CGAL::COLLINEAR) {
    return false;
}
// Verify that all turns are consistent with the initial orientation
for (std::size_t i = 0; i < n; ++i) {
    const auto& a = polygon[i];
    const auto& b = polygon[(i + 1) % n];
    const auto& c = polygon[(i + 2) % n];
    CGAL::Orientation o = CGAL::orientation(a, b, c);
    if (o != CGAL::COLLINEAR && o != first_non_collinear) {
        return false;
    }
}
return true;

